describe('Session Expiration After Inactivity', () => {
  const loginUrl = 'http://localhost:3000/login';
  const dashboardUrl = 'http://localhost:3000/dashboard';
  const loginPageSelector = '[data-testid="login-form"]';
  const dashboardSelector = '[data-testid="dashboard-content"]';
  const sessionExpiredSelector = '[data-testid="session-expired-message"]';
  const logoutSelector = '[data-testid="logout-button"]';

  beforeEach(() => {
    cy.visit(loginUrl);
    cy.get('[data-testid="email-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('ValidPassword123!');
    cy.get('[data-testid="login-button"]').click();
    cy.url().should('include', dashboardUrl);
    cy.get(dashboardSelector).should('be.visible');
  });

  it('should expire session after 30 minutes of inactivity', () => {
    cy.get(dashboardSelector).should('be.visible');

    cy.clock();

    cy.tick(30 * 60 * 1000);

    cy.visit(dashboardUrl);

    cy.get(sessionExpiredSelector).should('be.visible');
    cy.contains('Your session has expired').should('exist');
    cy.url().should('include', loginUrl);
  });

  it('should reset inactivity timer on user activity', () => {
    cy.get(dashboardSelector).should('be.visible');

    cy.clock();

    cy.tick(15 * 60 * 1000);

    cy.get('[data-testid="user-action-button"]').click();

    cy.tick(15 * 60 * 1000);

    cy.get(dashboardSelector).should('be.visible');
    cy.url().should('include', dashboardUrl);

    cy.tick(15 * 60 * 1000);

    cy.visit(dashboardUrl);
    cy.get(sessionExpiredSelector).should('be.visible');
  });

  it('should show warning before session expires', () => {
    cy.get(dashboardSelector).should('be.visible');

    cy.clock();

    cy.tick(28 * 60 * 1000);

    cy.get('[data-testid="session-warning-modal"]').should('be.visible');
    cy.contains('Your session will expire in 2 minutes').should('exist');
  });

  it('should allow user to extend session from warning modal', () => {
    cy.get(dashboardSelector).should('be.visible');

    cy.clock();

    cy.tick(28 * 60 * 1000);

    cy.get('[data-testid="session-warning-modal"]').should('be.visible');
    cy.get('[data-testid="extend-session-button"]').click();

    cy.get('[data-testid="session-warning-modal"]').should('not.exist');
    cy.get(dashboardSelector).should('be.visible');

    cy.tick(29 * 60 * 1000);

    cy.get(dashboardSelector).should('be.visible');
  });

  it('should expire session if user does not extend from warning', () => {
    cy.get(dashboardSelector).should('be.visible');

    cy.clock();

    cy.tick(28 * 60 * 1000);

    cy.get('[data-testid="session-warning-modal"]').should('be.visible');

    cy.tick(2 * 60 * 1000);

    cy.get(sessionExpiredSelector).should('be.visible');
    cy.url().should('include', loginUrl);
  });

  it('should maintain session across page navigation within activity window', () => {
    cy.get(dashboardSelector).should('be.visible');

    cy.clock();

    cy.tick(10 * 60 * 1000);

    cy.get('[data-testid="profile-link"]').click();
    cy.url().should('include', '/profile');
    cy.get('[data-testid="profile-content"]').should('be.visible');

    cy.tick(10 * 60 * 1000);

    cy.get('[data-testid="settings-link"]').click();
    cy.url().should('include', '/settings');
    cy.get('[data-testid="settings-content"]').should('be.visible');

    cy.tick(10 * 60 * 1000);

    cy.visit(dashboardUrl);
    cy.get(sessionExpiredSelector).should('be.visible');
  });
});
